// Generated by tools/build.py from src/40-book.js.
(() => {
  const reduce = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
  const toastEl = document.getElementById('toast');
  let toastTimer;
  const toast = (msg) => {
    if (!toastEl) return;
    toastEl.textContent = msg;
    toastEl.classList.add('show');
    clearTimeout(toastTimer);
    toastTimer = setTimeout(() => toastEl.classList.remove('show'), 1800);
  };

  /* Running folio: the current chapter slides into the bar */
  const folioNow = document.querySelector('.folio-now');
  const fNo = document.querySelector('[data-folio-no]');
  const fTitle = document.querySelector('[data-folio-title]');
  const chapters = [...document.querySelectorAll('[data-chapter]')];
  let current = null;
  const setFolio = (el) => {
    if (!el || el === current) return;
    current = el;
    const apply = () => { fNo.textContent = el.dataset.chapter; fTitle.textContent = el.dataset.chapterTitle; };
    if (reduce) { apply(); return; }
    folioNow.classList.add('swap');
    setTimeout(() => { apply(); folioNow.classList.remove('swap'); }, 180);
  };
  if ('IntersectionObserver' in window && chapters.length) {
    const io = new IntersectionObserver((entries) => {
      const visible = entries.filter(e => e.isIntersecting).sort((a, b) => a.boundingClientRect.top - b.boundingClientRect.top);
      if (visible.length) setFolio(visible[0].target);
    }, { rootMargin: '-45% 0px -50% 0px' });
    chapters.forEach(c => io.observe(c));
  }

  /* Masked reveals: visible at rest. Armed only after the reader scrolls, and only for photographs still below the fold. */
  const reveals = [...document.querySelectorAll('[data-reveal]')];
  const revealIO = 'IntersectionObserver' in window ? new IntersectionObserver((entries) => {
    entries.forEach(e => { if (e.isIntersecting) { e.target.classList.add('in'); revealIO.unobserve(e.target); } });
  }, { threshold: 0.18 }) : null;
  const arm = () => {
    if (reduce || !revealIO) return;
    const vh = window.innerHeight;
    reveals.forEach(el => {
      if (el.id === 'motion-fig') return;
      if (el.getBoundingClientRect().top > vh * 1.05) { el.classList.add('armed'); revealIO.observe(el); }
    });
  };
  window.addEventListener('scroll', arm, { once: true, passive: true });

  const replay = document.getElementById('replay');
  const motionFig = document.getElementById('motion-fig');
  if (replay && motionFig) {
    replay.addEventListener('click', () => {
      if (reduce) { toast('Reduced motion is on, so the reveal is instant.'); return; }
      motionFig.classList.remove('in');
      motionFig.classList.add('armed');
      void motionFig.offsetWidth;
      requestAnimationFrame(() => motionFig.classList.add('in'));
    });
  }

  /* Save toggles */
  document.querySelectorAll('[data-save]').forEach(btn => {
    btn.addEventListener('click', (ev) => {
      ev.preventDefault();
      const on = btn.getAttribute('aria-pressed') !== 'true';
      btn.setAttribute('aria-pressed', String(on));
      const label = btn.querySelector('span');
      if (label) label.textContent = on ? 'Saved' : 'Save';
      toast(on ? 'Saved to your homes (sample)' : 'Removed from your homes');
    });
  });

  /* Sample forms: validate, then confirm inline. Nothing is sent. */
  document.querySelectorAll('[data-demo-form]').forEach(form => {
    form.addEventListener('submit', (ev) => {
      ev.preventDefault();
      let ok = true;
      form.querySelectorAll('[required]').forEach(input => {
        const field = input.closest('.field');
        const err = field && field.querySelector('.err');
        const bad = !input.value.trim() || (input.type === 'email' && !/^\S+@\S+\.\S+$/.test(input.value.trim()));
        if (field) field.classList.toggle('error', bad);
        input.setAttribute('aria-invalid', String(bad));
        if (err) { err.hidden = !bad; if (bad) { err.id = err.id || ('err-' + input.id); input.setAttribute('aria-describedby', err.id); } }
        if (bad && ok) { input.focus(); ok = false; }
      });
      const confirm = form.querySelector('.confirm');
      if (ok && confirm) confirm.classList.add('show');
    });
  });

  /* Copy hex values */
  document.querySelectorAll('[data-copy]').forEach(btn => {
    btn.addEventListener('click', () => {
      const val = btn.dataset.copy;
      const done = () => { const t = btn.textContent; btn.textContent = 'Copied'; toast(val + ' copied'); setTimeout(() => btn.textContent = t, 1400); };
      if (navigator.clipboard && navigator.clipboard.writeText) {
        navigator.clipboard.writeText(val).then(done, () => toast('Select and copy: ' + val));
      } else { toast('Select and copy: ' + val); }
    });
  });
})();
